export const FD_EN = { us: 'CD (certificate of deposit)', ca: 'GIC', au: 'Term deposit', nz: 'Term deposit', gb: 'Fixed-rate savings bond', ie: 'Term deposit', sg: 'Fixed deposit', my: 'Fixed deposit', za: 'Fixed deposit', in: 'Fixed deposit (FD)' };

export function makeT(lang) {
  const d = STR[lang] || STR.en;
  return (key, vars) => {
    let s = d[key] ?? STR.en[key] ?? key;
    if (vars) s = s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] !== undefined ? vars[k] : `{${k}}`)).replace(/\.\.(?=\s|$)/g, '.');
    return s;
  };
}
export const RTL = new Set(['ar']);
